INSERT INTO public.products (id, external_ref, code, name, tagline, description, brand_id, category_id, environment, finish, coverage, spread_rate_m2_per_gal, drying_time, features, image_url, tech_sheet_url, rating, reviews_count, is_popular, badge, status, created_at, updated_at, tax_rate) VALUES ('933ecc0c-8b65-43d8-87d6-3fe031e3b0c7', 'prod-koraza-5', 'PNT-EXT-001', 'Koraza 5 Años Protección Total', 'Pintura elastomérica exterior antihongos con máxima resistencia a la intemperie y rayos UV', 'Pintura para exteriores 100% acrílica, base agua, diluible con agua. Máxima durabilidad con tecnología biosida activa contra hongos y algas. Puentea microfisuras de hasta 0.5 mm y repele agua de lluvia mientras permite transpirar al muro.', 'bf170ba1-12ce-4f6f-a595-5fbda693c4d2', 'c44fd060-0bd0-4360-8800-66aa19430028', 'Exterior', 'Mate', '20 a 25 m²/galón a 2 manos sobre superficie sellada', 22.00, 'Al tacto: 1 hora | Entre manos: 2 a 3 horas', '{"Garantía de durabilidad de 5 años certificada","Puenteo elástico de microfisuras hasta 0.5 mm","Alta resistencia a la radiación UV y decoloración","Excelente lavabilidad y bajo ensuciamiento","Bajo olor y cero solventes agresivos (Bajo VOC)"}', 'https://images.unsplash.com/photo-1589939705384-5185137a7f0f?auto=format&fit=crop&q=80&w=600', 'https://pintuco.com.co/fichas-tecnicas/koraza-5-anos.pdf', 4.9, 142, true, 'Más Vendido en Fachadas', 'ACTIVO', '2026-08-30 06:43:45.990247+00', '2026-08-30 06:43:45.990247+00', 19.00);
INSERT INTO public.products (id, external_ref, code, name, tagline, description, brand_id, category_id, environment, finish, coverage, spread_rate_m2_per_gal, drying_time, features, image_url, tech_sheet_url, rating, reviews_count, is_popular, badge, status, created_at, updated_at, tax_rate) VALUES ('8d4f1c0e-e4b4-4292-99b2-b3be5eda0cc4', 'prod-viniltex-avanzada', 'PNT-INT-002', 'Viniltex Avanzada Máxima Lavabilidad', 'Pintura Tipo 1 superlavable con agentes antibacteriales y cero salpicadura', 'Vinilo Tipo 1 premium para interiores de altísimo desempeño. Fórmula con resina 100% acrílica modificada que permite remover manchas difíciles con facilidad. Con tecnología antimicrobiana que inhibe hasta el 99.9% de bacterias.', 'bf170ba1-12ce-4f6f-a595-5fbda693c4d2', 'c7e7b182-b5ba-46c5-82db-e0721dd29666', 'Interior', 'Mate', '40 a 50 m²/galón a 2 manos sobre superficie estucada', 45.00, 'Al tacto: 30 min | Segunda mano: 2 horas', '{"Máxima lavabilidad (> 800 ciclos de lavado según NTC 1335)","Protección antibacterial y antihongos activa","Ultra cubrimiento desde la primera mano","Mínimo salpicado durante la aplicación con rodillo","Acabado uniforme sedoso y elegante"}', 'https://images.unsplash.com/photo-1562259949-e8e7689d7828?auto=format&fit=crop&q=80&w=600', 'https://pintuco.com.co/fichas-tecnicas/viniltex-avanzada.pdf', 4.8, 310, true, 'Nº 1 en Interiores', 'ACTIVO', '2026-08-30 06:43:45.990247+00', '2026-08-30 06:43:45.990247+00', 19.00);
INSERT INTO public.products (id, external_ref, code, name, tagline, description, brand_id, category_id, environment, finish, coverage, spread_rate_m2_per_gal, drying_time, features, image_url, tech_sheet_url, rating, reviews_count, is_popular, badge, status, created_at, updated_at, tax_rate) VALUES ('1dd0d17a-6f5c-4017-9f93-fe9eaba18b80', 'prod-aquablock-techos', 'PNT-IMP-003', 'Aquablock Fibratado Techos & Terrazas 8 Años', 'Impermeabilizante elastomérico reforzado con fibras para losas, cubiertas y terrazas transitables', 'Impermeabilizante acrílico con fibras incorporadas que sustituyen la tela de refuerzo en áreas continuas. Altamente elástico, no se cuartea con el sol y resiste el tránsito peatonal liviano y estancamientos temporales de agua.', 'bf170ba1-12ce-4f6f-a595-5fbda693c4d2', 'bb6abb65-9af0-4ed7-8b71-ded7c5bbd6a3', 'Exterior', 'Satinado', '1.2 a 1.5 L/m² en 3 manos cruzadas (aprox. 12 m²/galón sistema completo)', 12.00, 'Entre manos: 3 a 4 horas | Curado total: 48 horas', '{"Garantía de estanqueidad de 8 años","Fibras de polímero que evitan desgarros estructurales","Refleja hasta el 85% de radiación solar (aislamiento térmico)","Puentea fisuras de contracción en losas de concreto","Fácil aplicación en frío con rodillo o brocha"}', 'https://images.unsplash.com/photo-1621905251189-08b45d6a269e?auto=format&fit=crop&q=80&w=600', 'https://pintuco.com.co/fichas-tecnicas/aquablock-techos.pdf', 4.9, 88, true, 'Máxima Impermeabilidad', 'ACTIVO', '2026-08-30 06:43:45.990247+00', '2026-08-30 06:43:45.990247+00', 19.00);
INSERT INTO public.products (id, external_ref, code, name, tagline, description, brand_id, category_id, environment, finish, coverage, spread_rate_m2_per_gal, drying_time, features, image_url, tech_sheet_url, rating, reviews_count, is_popular, badge, status, created_at, updated_at, tax_rate) VALUES ('ae4e5ab7-39f8-44d2-a5e0-083c01724c2b', 'prod-sellador-antialcalino', 'PNT-PREP-004', 'Sellador Antialcalino Pintuco Base Agua', 'Imprimante fijador que neutraliza la eflorescencia salina y uniformiza la absorción', 'Imprimación esencial para muros nuevos o intervenidos de concreto y revoque. Bloquea sales y humedad residual proveniente del sustrato, previniendo el ampollamiento y la decoloración de la pintura de acabado.', 'bf170ba1-12ce-4f6f-a595-5fbda693c4d2', 'c44fd060-0bd0-4360-8800-66aa19430028', 'Ambos', 'Mate', '25 a 35 m²/galón a 1 mano', 30.00, 'Al tacto: 45 min | Repinte: 2 horas', '{"Bloquea el salitre y la alcalinidad del cemento fresco","Mejora la adherencia de pinturas de fachada hasta un 60%","Ahorra pintura de acabado al sellar la porosidad","Secado ultrarrápido al tacto en 45 minutos"}', 'https://images.unsplash.com/photo-1513694203232-719a280e022f?auto=format&fit=crop&q=80&w=600', 'https://pintuco.com.co/fichas-tecnicas/sellador-antialcalino.pdf', 4.8, 95, true, 'Paso 1 Obligatorio', 'ACTIVO', '2026-08-30 06:43:45.990247+00', '2026-08-30 06:43:45.990247+00', 19.00);
INSERT INTO public.products (id, external_ref, code, name, tagline, description, brand_id, category_id, environment, finish, coverage, spread_rate_m2_per_gal, drying_time, features, image_url, tech_sheet_url, rating, reviews_count, is_popular, badge, status, created_at, updated_at, tax_rate) VALUES ('65a2d15d-3c16-4e97-bfb8-e9e595688bef', 'prod-pintulux-3en1', 'PNT-MET-006', 'Pintulux 3 en 1 Anticorrosivo + Esmalte', 'Transforma el óxido, protege el metal y entrega acabado brillante duradero en 1 solo paso', 'Esmalte alquídico de alta tecnología que actúa directamente sobre superficies metálicas ferrosas, incluso con óxido adherido. Neutraliza la corrosión, sella e impermeabiliza, brindando un acabado brillante de alta resistencia.', 'bf170ba1-12ce-4f6f-a595-5fbda693c4d2', 'a9f87ea7-9761-436b-a49a-ad905cf5e52d', 'Ambos', 'Brillante', '25 a 30 m²/galón a 2 manos', 28.00, 'Al tacto: 2 horas | Repinte: 6 a 8 horas', '{"Elimina la necesidad de aplicar anticorrosivo previo","Se aplica directamente sobre óxido firme","Alto brillo y resistencia al rayado y tráfico","Resistente a la intemperie, lluvia y calor"}', 'https://images.unsplash.com/photo-1509198397868-475647b2a1e5?auto=format&fit=crop&q=80&w=600', 'https://pintuco.com.co/fichas-tecnicas/pintulux-3en1.pdf', 4.7, 198, true, 'Directo al Óxido', 'ACTIVO', '2026-08-30 06:43:45.990247+00', '2026-08-30 06:43:45.990247+00', 19.00);
INSERT INTO public.products (id, external_ref, code, name, tagline, description, brand_id, category_id, environment, finish, coverage, spread_rate_m2_per_gal, drying_time, features, image_url, tech_sheet_url, rating, reviews_count, is_popular, badge, status, created_at, updated_at, tax_rate) VALUES ('0147f000-903c-4bcb-a225-4f9b63720080', 'prod-madetec-barniz', 'PNT-MAD-007', 'Madetec Barniz Poliuretano Exterior Filtro UV', 'Barniz transparente de máxima protección contra el sol, humedad y hongos en maderas', 'Barniz sintético formulado con resinas de poliuretano y filtros solares de última generación. Protege la madera contra la decoloración solar, lluvia y agentes biológicos, realzando las vetas naturales.', 'bf170ba1-12ce-4f6f-a595-5fbda693c4d2', '509932b0-2efe-46a6-b5b0-a9a2c199f6b1', 'Exterior', 'Brillante', '35 a 45 m²/galón a 1 mano', 40.00, 'Al tacto: 3 horas | Repinte: 12 horas', '{"Filtro solar UV que previene el resecamiento y oscurecimiento","Película elástica que acompaña las dilataciones de la madera","Acabado cristalino brillante o semibrillante","Alta resistencia a hongos y termitas"}', 'https://images.unsplash.com/photo-1546484396-fb3fc6f95f98?auto=format&fit=crop&q=80&w=600', 'https://pintuco.com.co/fichas-tecnicas/madetec-barniz.pdf', 4.8, 62, false, NULL, 'ACTIVO', '2026-08-30 06:43:45.990247+00', '2026-08-30 06:43:45.990247+00', 19.00);
INSERT INTO public.products (id, external_ref, code, name, tagline, description, brand_id, category_id, environment, finish, coverage, spread_rate_m2_per_gal, drying_time, features, image_url, tech_sheet_url, rating, reviews_count, is_popular, badge, status, created_at, updated_at, tax_rate) VALUES ('54dc1c33-faa8-4700-b4af-a93543c5585f', 'prod-epoxico-pintucoat', 'PNT-IND-008', 'Pintucoat Epóxico Alto Tráfico para Pisos', 'Recubrimiento epóxico de dos componentes para pisos de garajes, bodegas y clínicas', 'Sistema epóxico poliamida de alta resistencia química y mecánica. Soporta tráfico pesado de montacargas y vehículos, derrames de aceites, solventes y productos químicos de limpieza.', 'bf170ba1-12ce-4f6f-a595-5fbda693c4d2', '0d87c291-578d-446e-b6fe-d7a4bc1c2da8', 'Industrial', 'Brillante', '20 a 25 m²/galón a 2 manos (Kit Componente A + B)', 22.00, 'Tráfico liviano: 24 horas | Curado total: 7 días', '{"Resistencia extrema al tráfico pesado y abrasión","Superficie continua higiénica y antipolvo","Resistente a aceites, gasolina y detergentes industriales","Cumple normas de asepsia para áreas alimenticias y de salud"}', 'https://images.unsplash.com/photo-1581092160607-ee22621dd758?auto=format&fit=crop&q=80&w=600', 'https://pintuco.com.co/fichas-tecnicas/pintucoat-pisos.pdf', 4.9, 45, false, 'Industrial Pesado', 'ACTIVO', '2026-08-30 06:43:45.990247+00', '2026-08-30 06:43:45.990247+00', 19.00);
INSERT INTO public.products (id, external_ref, code, name, tagline, description, brand_id, category_id, environment, finish, coverage, spread_rate_m2_per_gal, drying_time, features, image_url, tech_sheet_url, rating, reviews_count, is_popular, badge, status, created_at, updated_at, tax_rate) VALUES ('efc0b51b-7b3f-4a91-90d8-83c804e8ca60', 'prod-rodillo-antigota', 'PNT-HER-009', 'Rodillo Profesional Microfibra Antigota Pintuco 9"', 'Rodillo de alta retención para acabados parejos sin salpique en vinilos y fachadas', 'Herramienta profesional con felpa de microfibra termofusionada de 3/8" (9 mm). Proporciona una transferencia óptima de pintura sobre la pared sin salpicar ni dejar marcas de rodillazo.', 'bf170ba1-12ce-4f6f-a595-5fbda693c4d2', 'c086030a-dc64-489d-860c-84d450c93089', 'Ambos', 'N/A', 'Ideal para proyectos de 20 a 500 m²', NULL, 'N/A', '{"Microfibra de alta densidad sin desprendimiento de hilos","Mango ergonómico con rosca para extensión","Ahorra hasta un 25% de tiempo de aplicación","Fácil lavado y reutilizable más de 15 veces"}', 'https://images.unsplash.com/photo-1589939705384-5185137a7f0f?auto=format&fit=crop&q=80&w=600', NULL, 4.9, 180, true, 'Herramienta Recomendada', 'ACTIVO', '2026-08-30 06:43:45.990247+00', '2026-08-30 06:43:45.990247+00', 19.00);
INSERT INTO public.products (id, external_ref, code, name, tagline, description, brand_id, category_id, environment, finish, coverage, spread_rate_m2_per_gal, drying_time, features, image_url, tech_sheet_url, rating, reviews_count, is_popular, badge, status, created_at, updated_at, tax_rate) VALUES ('9d570b03-1889-475a-b461-336b5bead3e6', 'prod-cinta-azul', 'PNT-HER-011', 'Cinta Azul Masking Profesional Pintuco 1.5"', 'Cinta de enmascarar de retiro limpio hasta 14 días sin dejar residuos de pegante', 'Cinta de papel crepé azul con adhesivo de polímero acrílico resistente a rayos UV. Brinda líneas de pintura nítidas y se retira fácilmente de molduras, marcos y vidrios sin dañar la superficie.', 'bf170ba1-12ce-4f6f-a595-5fbda693c4d2', 'c086030a-dc64-489d-860c-84d450c93089', 'Ambos', 'N/A', 'Rollo de 50 metros', NULL, 'N/A', '{"Líneas de pintura nítidas sin filtraciones","Remoción limpia hasta por 14 días bajo sol directo","Resistente a la humedad y pinturas base agua"}', 'https://images.unsplash.com/photo-1504307651254-35680f356dfd?auto=format&fit=crop&q=80&w=600', NULL, 4.9, 89, false, NULL, 'ACTIVO', '2026-08-30 06:43:45.990247+00', '2026-08-30 06:43:45.990247+00', 19.00);
INSERT INTO public.products (id, external_ref, code, name, tagline, description, brand_id, category_id, environment, finish, coverage, spread_rate_m2_per_gal, drying_time, features, image_url, tech_sheet_url, rating, reviews_count, is_popular, badge, status, created_at, updated_at, tax_rate) VALUES ('17ac316e-3224-4e57-94ad-192831f1ba4d', 'prod-masilla-elastomerica', 'PNT-PREP-005', 'Masilla Elastomérica Grietas & Fisuras Fachada', 'Masilla acrílica flexible para sello de fisuras y juntas con movimiento en exteriores', 'Compuesto elastomérico diseñado para sellar y reparar grietas de hasta 5 mm de ancho en muros exteriores e interiores. Gran elongación y memoria elástica, no se encoge ni se agrieta con la intemperie.', 'bf170ba1-12ce-4f6f-a595-5fbda693c4d2', 'c44fd060-0bd0-4360-8800-66aa19430028', 'Ambos', 'Texturizado', 'Rinde aprox. 15 metros lineales por cartucho de 300ml o 15 m² en fisurado general', 15.00, 'Al tacto: 2 horas | Lijado/Pintado: 12 horas', '{"Elongación superior al 300% para absorber dilataciones térmicas","Pintable con cualquier vinilo o pintura elastomérica Pintuco","Excelente adherencia sobre concreto, mortero y mampostería","Uso interior y exterior bajo intemperie severa"}', 'https://images.unsplash.com/photo-1504307651254-35680f356dfd?auto=format&fit=crop&q=80&w=600', NULL, 4.9, 74, true, NULL, 'ACTIVO', '2026-08-30 06:43:45.990247+00', '2026-08-30 07:00:29.580598+00', 19.00);
INSERT INTO public.products (id, external_ref, code, name, tagline, description, brand_id, category_id, environment, finish, coverage, spread_rate_m2_per_gal, drying_time, features, image_url, tech_sheet_url, rating, reviews_count, is_popular, badge, status, created_at, updated_at, tax_rate) VALUES ('fad94307-bc67-4fab-a7f0-84b2aee5c59b', 'prod-brocha-master', 'PNT-HER-010', 'Brocha Master Cerdas Mixtas Pintuco 3"', 'Brocha angular para recortes limpios en esquinas, marcos y detalles de fachada', 'Brocha con cerdas naturales y sintéticas de corte recto para un control milimétrico del trazo en remates y zócalos. Mango de madera balanceado y virola de acero inoxidable.', 'bf170ba1-12ce-4f6f-a595-5fbda693c4d2', 'c086030a-dc64-489d-860c-84d450c93089', 'Ambos', 'N/A', 'N/A', NULL, 'N/A', '{"Cerdas químicamente afiladas para un recorte perfecto","Excelente carga y descarga progresiva de pintura","No pierde cerdas durante la aplicación"}', 'https://cdn-pintuco-col.plm.com.co/wp-content/uploads/2023/01/brocha-estandar-cerda-blanca-3-pulg-pintuco-jpg.webp', NULL, 4.8, 112, false, NULL, 'ACTIVO', '2026-08-30 06:43:45.990247+00', '2026-09-03 00:25:40.164055+00', 19.00);
